<script setup lang="ts">import{computed,inject,watch}from'vue';import{useAppStore}from'../app/store';import{useModuleStore}from'../app/moduleStore';import type{ModuleClient}from'../bridge/clients/ModuleClient';import QPage from'../design-system/components/QPage.vue';import QPageHeader from'../design-system/components/QPageHeader.vue';import QCard from'../design-system/components/QCard.vue';import QBadge from'../design-system/components/QBadge.vue';const app=useAppStore();const modules=useModuleStore();const client=inject<ModuleClient>('moduleClient')!;watch(()=>app.bridge,bridge=>{if(bridge==='Connected'&&modules.status==='idle'){modules.begin();client.getSnapshot().then(x=>modules.complete(x)).catch(e=>modules.fail(e))}},{immediate:true});const valid=computed(()=>modules.modules.filter(x=>x.isValid).length);const running=computed(()=>modules.modules.filter(x=>x.runtimeState==='Running').length);const issues=computed(()=>modules.modules.filter(x=>x.errorCount>0).length)</script>
<template><QPage><QPageHeader title="Welcome back" description="A calm overview of your modular workspace."><QBadge tone="info">{{app.snapshot?.environmentDisplayName??'Development'}}</QBadge></QPageHeader><section class="hero"><div><span>QING WORKSPACE</span><h2>Your tools, clearly organized.</h2><p>Browse the modules known to the host without loading or changing them.</p><RouterLink class="q-button is-primary" to="/modules">View modules</RouterLink></div><div class="hero-mark">Q</div></section><section class="metric-grid"><QCard><label>Total modules</label><strong>{{modules.modules.length}}</strong><small>Discovered by the host</small></QCard><QCard><label>Valid modules</label><strong>{{valid}}</strong><small>Ready for use</small></QCard><QCard><label>Running</label><strong>{{running}}</strong><small>Current C# runtime state</small></QCard><QCard><label>Need attention</label><strong>{{issues}}</strong><small>Validation issues</small></QCard></section><section class="home-status"><QCard><h3>Host connection</h3><p><QBadge :tone="app.bridge==='Connected'?'success':'warning'">{{app.bridge}}</QBadge></p><dl><div><dt>Host version</dt><dd>{{app.snapshot?.hostVersion??'—'}}</dd></div><div><dt>Bridge protocol</dt><dd>v{{app.snapshot?.protocolVersion??4}}</dd></div></dl></QCard><QCard><h3>Workspace promise</h3><p>This view is read-only. Opening it never loads a module DLL or changes runtime state.</p></QCard></section></QPage></template>
